mapper.select:
SELECT A.STATUS status, A.IS_CONSIGN isConsign, A.ACCOUNT account, P.PRODNAME accountName, A.REGIST_BANK_CODE registBankCode, A.BUSI_SEQNO busiSeqno, A.EQUITY_CONF_DATE eQuityConfDate, to_char(A.EQUITY_CONF_DATE,'yyyy-MM-dd') eQuityConfDateStr, A.INDENTIFY_MARK indentifyMark, A.BUY_PLACE buyPlace, A.BUSI_TYPE busiType, A.CCY ccy, A.AMOUNT amount, A.COVER_CNY_AMOUNT converCnyAmount, A.SHARES shares, A.CHANNEL channel, A.FUND_ACC fundAcc, A.FUND_ACC_BANK fundAccBank, A.REMARK remark, P.REG_CODE regCode, A.ORG_CODE orgCode, A.AGENT agent, A.SHARE_CONF_DATETIME shareConfDatetime FROM CHB_EQUDET A LEFT JOIN CHB_PRDRESIST_CODE P ON A.ACCOUNT = P.PRODID AND A.ORG_CODE = P.ORG_CODE
#{orgCode,jdbcType=VARCHAR}
A.REGIST_BANK_CODE LIKE concat(concat('%',#{bankCode}),'%')
#{orgCode,jdbcType=VARCHAR}
#{prdCode,jdbcType=VARCHAR}
AND A.INDENTIFY_MARK LIKE concat(concat('%',#{indentifyMark}),'%')
#{busiType,jdbcType=VARCHAR}
AND A.EQUITY_CONF_DATE >= date( TIMESTAMP_FORMAT(#{eQuityConfDateStart},'yyyy-MM-dd'))
AND A.EQUITY_CONF_DATE <= date( TIMESTAMP_FORMAT(#{eQuityConfDateStart},'yyyy-MM-dd'))
#{status,jdbcType=VARCHAR}
#{channel,jdbcType=VARCHAR}
AND A.IS_CONSIGN = #{isConsign}
AND A.BUSI_SEQNO = #{busiSeqno}
(A.BUSI_SEQNO=#{paramMap.busiSeqnoKey} and A.REGIST_BANK_CODE=#{paramMap.registBankCodeKey} and A.INDENTIFY_MARK=#{paramMap.indentifyMarkKey})
ORDER BY A.UPDATE_TIME DESC,A.BUSI_SEQNO ASC
